# --------------------------------------------------
# أسعار دقيقة + العدادات تُحسب بسعر الحبة الواحدة
# --------------------------------------------------
PRICE_DECIMALS = 10


def _num(v, default=0.0):
    try:
        return float(v)
    except (TypeError, ValueError):
        return default


def counter_unit_price(sub):
    """سعر الحبة الواحدة للعداد (يدعم البيانات القديمة المخزنة بسعر أقل كمية)."""
    u = sub.get('counter_unit_price')
    if u not in (None, ''):
        return _num(u)
    min_qty = max(1, int(_num(sub.get('counter_min_qty', 1), 1) or 1))
    min_price = _num(sub.get('counter_min_price', sub.get('price', 0)))
    return min_price / min_qty


def set_counter_unit_price(sub, unit):
    """يخزّن سعر الحبة بدقة كاملة، ويبقي counter_min_price للتوافق مع القديم."""
    unit = round(float(unit), PRICE_DECIMALS)
    min_qty = max(1, int(_num(sub.get('counter_min_qty', 1), 1) or 1))
    sub['counter_unit_price'] = unit
    sub['price'] = unit
    sub['counter_min_price'] = round(unit * min_qty, PRICE_DECIMALS)


def _migrate_counter_unit_prices():
    changed = 0
    for s in SUBCATEGORIES_DATA:
        if not s.get('is_counter') or s.get('counter_unit_price') not in (None, ''):
            continue
        if s.get('api_product_id') and s.get('base_price') not in (None, ''):
            unit = _num(s.get('base_price')) * (1 + _num(s.get('profit_margin', 0)) / 100.0)
        else:
            unit = counter_unit_price(s)
        set_counter_unit_price(s, unit)
        changed += 1
    if changed:
        save_json_file(SUBCATEGORIES_FILE, SUBCATEGORIES_DATA)
        logging.info(f"تم تحويل {changed} عداد إلى حساب سعر الحبة الواحدة")


_migrate_counter_unit_prices()

