def get_user_by_api_token(token):
    if not token:
        return None
    for email, udata in USERS_DATA.items():
        if udata.get('api_token') == token and udata.get('api_enabled', False):
            return email, udata
    return None


def make_api_request(url, token, timeout=12):
    headers = {
        'api-token': token,
        'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36',
        'Accept': 'application/json'
    }
    req = urllib.request.Request(url, headers=headers)
    with urllib.request.urlopen(req, timeout=timeout) as response:
        return json.loads(response.read().decode('utf-8'))


def _tg_rich_text_for(email, order_uuid, message, status):
    """يبني رسالة تلغرام مفصّلة لقبول/رفض الإيداع أو الطلب (أو نص عادي إن لم يُعرف النوع)."""
    ok = (status == "success")
    sep = "━━━━━━━━━━━━━━"
    try:
        bal = tg_money((USERS_DATA.get(email) or {}).get("balance", 0))
        if str(order_uuid).startswith("deposit_"):
            rid = str(order_uuid)[len("deposit_"):]
            req = next((r for r in DEPOSIT_REQUESTS_DATA if str(r.get("id")) == rid), None)
            if req:
                head = "✅ <b>تم قبول طلب الإيداع</b>" if ok else "❌ <b>تم رفض طلب الإيداع</b>"
                txt = (f"{head}\n{sep}\n"
                       f"💳 <b>طريقة الإيداع:</b> {tg_esc(req.get('method_name', '-'))}\n"
                       f"💰 <b>المبلغ:</b> {tg_money(req.get('amount', 0))} $\n"
                       f"🧾 <b>رقم العملية:</b> <code>{tg_esc(req.get('tx_id', '-'))}</code>\n")
                if ok:
                    txt += f"{sep}\n💵 <b>رصيدك الآن:</b> {bal} $"
                else:
                    txt += f"{sep}\n💵 <b>رصيدك:</b> {bal} $"
                return txt
        else:
            o = next((x for x in ORDERS_DATA if x.get("order_uuid") == order_uuid), None)
            if o:
                head = "✅ <b>تم تنفيذ طلبك</b>" if ok else "❌ <b>تم رفض طلبك</b>"
                txt = (f"{head}\n{sep}\n"
                       f"📦 <b>المنتج:</b> {tg_esc(o.get('product', '-'))}\n"
                       f"🏷️ <b>الفئة:</b> {tg_esc(o.get('subcategory', '-'))}\n"
                       f"💰 <b>السعر:</b> {tg_money(o.get('price', 0))} $\n"
                       f"📝 <b>المدخلات:</b> {tg_esc(o.get('input', '-'))}\n"
                       f"🆔 <b>رقم الطلب:</b> <code>{tg_esc(str(order_uuid)[:16])}</code>\n")
                if not ok:
                    txt += f"↩️ <b>تم إرجاع المبلغ إلى رصيدك</b>\n"
                txt += f"{sep}\n💵 <b>رصيدك الآن:</b> {bal} $"
                return txt
    except Exception as e:
        logging.error(f"فشل بناء رسالة التلغرام المفصلة: {e}")
    return f"🔔 {html_lib.escape(str(message))}"


def add_user_notification(email, order_uuid, message, status, tg_text=None):
    if email not in NOTIFICATIONS_DATA:
        NOTIFICATIONS_DATA[email] = []

    notif_id = str(uuid.uuid4())
    NOTIFICATIONS_DATA[email].insert(0, {
        "id": notif_id,
        "order_uuid": order_uuid,
        "message": message,
        "status": status,
        "is_read": False,
        "timestamp": datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    })

    NOTIFICATIONS_DATA[email] = NOTIFICATIONS_DATA[email][:50]
    save_json_file(NOTIFICATIONS_FILE, NOTIFICATIONS_DATA)

    # نفس الإشعار يوصل لحساب المستخدم في بوت التلغرام (إن كان مربوطاً)
    try:
        tg_notify_user(email, tg_text or _tg_rich_text_for(email, order_uuid, message, status))
    except Exception as e:
        logging.error(f"فشل إشعار التلغرام: {e}")

    # إشعار نظامي على جهاز المستخدم عبر المتصفح (Web Push)
    try:
        send_web_push_async(email, "SYRIA CARD ONE", str(message), notif_id)
    except Exception as e:
        logging.error(f"فشل إشعار المتصفح: {e}")


# --------------------------------------------------
# نظام متابعة الطلبات المستمرة (Order Polling System)
# --------------------------------------------------
class OrderPollingSystem:
    def __init__(self, check_interval=60):
        self.check_interval = check_interval
        self.active_orders = {}
        self.lock = threading.Lock()
        self.running = True

        self.monitor_thread = threading.Thread(target=self._monitor_new_orders, daemon=True)
        self.monitor_thread.start()
        logging.info("تم تشغيل نظام متابعة الطلبات المستمرة")

    def add_order(self, order_uuid, provider_name, api_product_id, email, price):
        with self.lock:
            if order_uuid not in self.active_orders:
                thread = threading.Thread(
                    target=self._poll_order,
                    args=(order_uuid, provider_name, api_product_id, email, price),
                    daemon=True
                )
                self.active_orders[order_uuid] = {
                    'thread': thread,
                    'status': 'active',
                    'created_at': datetime.now()
                }
                thread.start()
                logging.info(f"تم إضافة الطلب {order_uuid} للمتابعة المستمرة")

    def _monitor_new_orders(self):
        while self.running:
            try:
                with self.lock:
                    for order in ORDERS_DATA:
                        if (order.get('api_product_id') and
                            order.get('status') in ["قيد الانتظار", "تم الارسال للتشيك"] and
                            order.get('order_uuid') not in self.active_orders):
                            self.add_order(
                                order_uuid=order.get('order_uuid'),
                                provider_name=order.get('provider_name'),
                                api_product_id=order.get('api_product_id'),
                                email=order.get('email'),
                                price=order.get('price')
                            )
            except Exception as e:
                logging.error(f"خطأ في مراقبة الطلبات الجديدة: {e}")

            time.sleep(10)

    def _poll_order(self, order_uuid, provider_name, api_product_id, email, price):
        logging.info(f"بدء متابعة الطلب {order_uuid}")

        while self.running:
            try:
                target_order = None
                for order in ORDERS_DATA:
                    if order.get('order_uuid') == order_uuid:
                        target_order = order
                        break

                if not target_order:
                    logging.warning(f"الطلب {order_uuid} غير موجود، إيقاف المتابعة")
                    break

                if target_order.get('status') not in ["قيد الانتظار", "تم الارسال للتشيك"]:
                    logging.info(f"تم معالجة الطلب {order_uuid} - الحالة: {target_order.get('status')}")
                    break

                provider = next(
                    (p for p in PROVIDERS_DATA if p.get('name') == provider_name),
                    PROVIDERS_DATA[0] if PROVIDERS_DATA else None
                )

                if not provider:
                    logging.error(f"لا يوجد مزود للطلب {order_uuid}")
                    time.sleep(self.check_interval)
                    continue

                token = provider.get('token')
                url = provider.get('url', '').rstrip('/') + '/'

                check_url = f"{url}client/api/check?orders=[{order_uuid}]&uuid=1"

                try:
                    res = make_api_request(check_url, token, timeout=10)

                    if res.get('status') == "OK" and res.get('data') and len(res['data']) > 0:
                        api_status = res['data'][0].get('status')
                        api_order_id = res['data'][0].get('order_id', '')
                        replay_api = res['data'][0].get('replay_api')

                        logging.info(f"الطلب {order_uuid} - حالة API: {api_status}")

                        if api_status == "accept":
                            target_order['status'] = "مكتملة"
                            target_order['api_order_id'] = api_order_id
                            target_order['replay_api'] = replay_api
                            target_order['updated_at'] = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
                            save_json_file(ORDERS_FILE, ORDERS_DATA)

                            user_pwd = USERS_DATA.get(email, {}).get('password', 'غير معروف')
                            send_telegram_status_change_notification(target_order, "مكتملة", user_pwd)

                            add_user_notification(
                                email=email,
                                order_uuid=order_uuid,
                                message=f"تم قبول طلبك: {target_order.get('subcategory', '')}",
                                status="success"
                            )

                            logging.info(f"تم قبول الطلب {order_uuid}")
                            break

                        elif api_status == "reject":
                            if target_order.get('status') == "مرفوضة":
                                logging.warning(f"الطلب {order_uuid} مرفوض مسبقاً، تجاهل")
                                break
                            
                            target_order['status'] = "مرفوضة"
                            target_order['api_order_id'] = api_order_id
                            target_order['replay_api'] = replay_api
                            target_order['updated_at'] = datetime.now().strftime("%Y-%m-%d %H:%M:%S")

                            if email in USERS_DATA:
                                current_bal = round(float(USERS_DATA[email].get('balance', 0)), 10)
                                USERS_DATA[email]['balance'] = round(current_bal + float(price), 10)
                                save_json_file(USERS_FILE, USERS_DATA)
                                logging.info(f"تم رفض الطلب {order_uuid} وإعادة المبلغ للمستخدم")

                            save_json_file(ORDERS_FILE, ORDERS_DATA)

                            user_pwd = USERS_DATA.get(email, {}).get('password', 'غير معروف')
                            send_telegram_status_change_notification(target_order, "مرفوضة", user_pwd)

                            add_user_notification(
                                email=email,
                                order_uuid=order_uuid,
                                message=f"تم رفض طلبك وإعادة المبلغ: {target_order.get('subcategory', '')}",
                                status="error"
                            )

                            break

                        elif api_status == "wait":
                            if target_order.get('status') != "تم الارسال للتشيك":
                                target_order['status'] = "تم الارسال للتشيك"
                                target_order['updated_at'] = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
                                save_json_file(ORDERS_FILE, ORDERS_DATA)
                            logging.info(f"الطلب {order_uuid} لا يزال قيد الانتظار")

                    else:
                        logging.warning(f"استجابة غير متوقعة للطلب {order_uuid}: {res}")

                except Exception as e:
                    logging.error(f"خطأ في فحص الطلب {order_uuid}: {e}")

            except Exception as e:
                logging.error(f"خطأ في متابعة الطلب {order_uuid}: {e}")

            time.sleep(self.check_interval)

        with self.lock:
            if order_uuid in self.active_orders:
                del self.active_orders[order_uuid]

        logging.info(f"انتهت متابعة الطلب {order_uuid}")


order_polling_system = OrderPollingSystem(check_interval=60)


# --------------------------------------------------
# نظام مراقبة أسعار API كل 5 دقائق
# --------------------------------------------------
class ApiPriceMonitor:
    def __init__(self, check_interval=300):
        self.check_interval = check_interval
        self.running = True
        self.monitor_thread = threading.Thread(target=self._monitor_prices, daemon=True)
        self.monitor_thread.start()
        logging.info("تم تشغيل نظام مراقبة أسعار API")

    def _monitor_prices(self):
        while self.running:
            try:
                self._check_all_api_linked_subcategories()
            except Exception as e:
                logging.error(f"خطأ في مراقبة أسعار API: {e}")

            time.sleep(self.check_interval)

    def _check_all_api_linked_subcategories(self):
        """مراقبة أسعار جميع الفئات المربوطة بـ API (سواء مستوردة أو مضافة يدوياً)"""
        
        # نجمع كل الفئات المربوطة بـ API حسب المزود
        subcats_by_provider = {}
        for sub in SUBCATEGORIES_DATA:
            provider_name = sub.get('provider_name')
            api_product_id = sub.get('api_product_id')
            
            if provider_name and api_product_id:
                if provider_name not in subcats_by_provider:
                    subcats_by_provider[provider_name] = []
                subcats_by_provider[provider_name].append(sub)

        if not subcats_by_provider:
            logging.info("لا توجد فئات مربوطة بـ API حالياً للمراقبة")
            return

        # نفحص كل مزود على حدة
        for provider_name, subcats in subcats_by_provider.items():
            provider = next((p for p in PROVIDERS_DATA if p.get('name') == provider_name), None)
            if not provider:
                logging.warning(f"المزود {provider_name} غير موجود في القائمة")
                continue

            token = provider.get('token')
            base_url = provider.get('url', '').rstrip('/') + '/'

            try:
                products_url = f"{base_url}client/api/products"
                api_products = make_api_request(products_url, token, timeout=15)

                if not isinstance(api_products, list):
                    logging.warning(f"استجابة المزود {provider_name} ليست قائمة منتجات")
                    continue

                # نبني قاموس للوصول السريع
                api_map = {}
                for ap in api_products:
                    api_map[str(ap.get('id'))] = ap

                updated_count = 0
                desc_changed = False
                price_changes = []

                for subcat in subcats:
                    api_id = str(subcat.get('api_product_id', ''))
                    api_product = api_map.get(api_id)

                    if not api_product:
                        logging.warning(f"لم يتم العثور على المنتج {api_id} لدى المزود {provider_name}")
                        continue

                    is_ctr = bool(subcat.get('is_counter'))
                    old_price = counter_unit_price(subcat) if is_ctr else _num(subcat.get('price', 0))
                    old_base = _num(subcat.get('base_price', 0))

                    # السعر الأساسي الجديد من المزود
                    _raw_base = api_product.get('base_price')
                    if _raw_base in (None, ''):
                        _raw_base = api_product.get('price')
                    new_base = _num(_raw_base, old_base) if _raw_base not in (None, '') else old_base
                    # حماية: إذا رجع المزود سعراً فارغاً/صفراً لا نصفّر سعر المنتج
                    if new_base <= 0 and old_base > 0:
                        new_base = old_base

                    # نسبة الربح المخزنة للفئة
                    profit_margin = _num(subcat.get('profit_margin', 0))

                    # السعر النهائي بعد الربح (للعدادات: سعر الحبة الواحدة)
                    new_price = round(new_base * (1 + (profit_margin / 100.0)), PRICE_DECIMALS)

                    # مزامنة الوصف من الـ API (بدون المساس بوصف عدّلته يدوياً)
                    new_desc, new_desc_real = api_description(api_product)
                    if new_desc and (not subcat.get('description') or subcat.get('desc_api')) \
                            and subcat.get('description') != new_desc:
                        subcat['description'] = new_desc
                        subcat['desc_api'] = True
                        desc_changed = True
                    elif not new_desc and subcat.get('desc_api') and _is_auto_desc(subcat.get('description'), api_product):
                        subcat['description'] = ''
                        subcat['desc_api'] = False
                        desc_changed = True

                    # مزامنة متطلبات الشراء (مستطيلات الإدخال بنافذة الشراء)
                    _lbls = _api_param_labels(api_product)
                    if _lbls != (subcat.get('api_params') or []):
                        if _lbls:
                            subcat['api_params'] = _lbls
                        else:
                            subcat.pop('api_params', None)
                        desc_changed = True

                    # إذا كان في تغيير (مقارنة نسبية دقيقة حتى مع الأسعار الصغيرة جداً)
                    price_diff = abs(new_price - old_price) > (1e-12 + 1e-9 * abs(old_price))
                    base_diff = abs(new_base - old_base) > (1e-12 + 1e-9 * abs(old_base))
                    if price_diff or base_diff:
                        subcat['base_price'] = new_base
                        if is_ctr:
                            set_counter_unit_price(subcat, new_price)
                        else:
                            subcat['price'] = new_price

                        updated_count += 1

                        change_type = "ارتفاع" if new_price > old_price else "انخفاض"
                        price_changes.append({
                            "name": subcat.get('name'),
                            "old_price": old_price,
                            "new_price": new_price,
                            "change_type": change_type
                        })

                if desc_changed and updated_count == 0:
                    save_json_file(SUBCATEGORIES_FILE, SUBCATEGORIES_DATA)
                    logging.info(f"تم تحديث أوصاف الفئات من المزود: {provider_name}")
                elif updated_count > 0:
                    save_json_file(SUBCATEGORIES_FILE, SUBCATEGORIES_DATA)
                    logging.info(f"تم تحديث {updated_count} سعر من المزود: {provider_name}")
                    self._send_price_change_notification(provider_name, price_changes)
                else:
                    logging.info(f"لا توجد تغييرات في أسعار المزود {provider_name} - عدد الفئات المفحوصة: {len(subcats)}")

                # نحدث وقت آخر فحص للمستوردين
                for import_key, import_info in API_IMPORTS_DATA.items():
                    if import_info.get('provider_name') == provider_name:
                        API_IMPORTS_DATA[import_key]['last_price_check'] = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
                save_json_file(API_IMPORTS_FILE, API_IMPORTS_DATA)

            except Exception as e:
                logging.error(f"خطأ في فحص أسعار المزود {provider_name}: {e}")

    def _send_price_change_notification(self, provider_name, price_changes):
        _tg_tok, _tg_chat = tg_notify_target("prices")
        if not _tg_tok or _tg_tok == "YOUR_TELEGRAM_BOT_TOKEN":
            return

        if not price_changes:
            return

        telegram_url = f"https://api.telegram.org/bot{_tg_tok}/sendMessage"
        headers = {"Content-Type": "application/json"}

        changes_text = ""
        for change in price_changes[:10]:
            emoji = "📈" if change['change_type'] == "ارتفاع" else "📉"
            changes_text += f"{emoji} {change['name']}: {change['old_price']}$ → {change['new_price']}$ ({change['change_type']})\n"

        if len(price_changes) > 10:
            changes_text += f"\n... و {len(price_changes) - 10} تغيير آخر"

        message = (
            f'<tg-emoji emoji-id="5409048419211682843">💰</tg-emoji> <b>تحديث أسعار API</b>\n'
            f'ــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــ\n'
            f'<tg-emoji emoji-id="5253742260054409879">🏷️</tg-emoji> <b>المزود:</b> {provider_name}\n'
            f'<tg-emoji emoji-id="5839437853469186962">📊</tg-emoji> <b>عدد التغييرات:</b> {len(price_changes)}\n'
            f'ــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــ\n'
            f'{changes_text}'
        )

        payload = json.dumps({
            "chat_id": _tg_chat,
            "text": message,
            "parse_mode": "HTML"
        }).encode("utf-8")

        try:
            req = urllib.request.Request(telegram_url, data=payload, headers=headers, method="POST")
            with urllib.request.urlopen(req, timeout=8) as res:
                logging.info(f"تم إرسال إشعار تغييرات الأسعار للمزود {provider_name}")
        except Exception as e:
            logging.error(f"فشل إرسال إشعار تغييرات الأسعار: {e}")


api_price_monitor = ApiPriceMonitor(check_interval=300)


# --------------------------------------------------
# استيراد شجرة كاملة من الـ API (يعمل بالخلفية وبهدوء مع عدادات حية)
#   قسم (من الـ API)
#     └ قسم فرعي  ← يظهر بالمتجر كبطاقة منتج
#         └ منتج  ← يظهر بالمتجر كمجموعة فرعية
#             └ فئة (الشيء القابل للشراء + وصفه + سعره)
#   - الفئات ممكن تكون مباشرة تحت القسم الفرعي أو تحت المنتج أو حتى تحت القسم نفسه
#   - لو الشجرة أعمق من كذا، المستويات الزيادة بتنسطّح داخل المنتج (باسم الفرع كبادئة)
# --------------------------------------------------
API_IMPORT_SCHEMA = 2          # رقم نسخة صيغة البيانات المستوردة (الأقدم تعتبر قديمة)
IMPORT_STEP_DELAY = 0.6        # انتظار بعد كل طلب لقسم (ثواني) حتى يكون السحب على مهله
IMPORT_ITEM_DELAY = 0.03       # انتظار صغير بعد كل فئة حتى تتحرك العدادات بشكل واضح
IMPORT_MAX_DEPTH = 8           # أقصى عمق للشجرة (حماية من التكرار اللانهائي)

IMPORT_JOBS = {}
IMPORT_JOBS_LOCK = threading.Lock()
DATA_LOCK = threading.RLock()


class ImportCancelled(Exception):
    pass


def _strip_html(text):
    if not isinstance(text, str):
        return ''
    text = re.sub(r'(?i)<br\s*/?>|</p>|</li>|</div>', '\n', text)
    text = re.sub(r'<[^>]+>', '', text)
    text = html_lib.unescape(text)
    text = re.sub(r'[ \t]+', ' ', text)
    text = re.sub(r'\n\s*\n+', '\n', text)
    return text.strip()


def _first_value(d, keys):
    if not isinstance(d, dict):
        return ''
    for k in keys:
        v = d.get(k)
        if v not in (None, '', [], {}):
            return v
    return ''


def _node_name(d):
    return str(_first_value(d, ('name', 'title', 'category_name', 'اسم')) or '').strip()


DESC_KEYS = (
    'description', 'desc', 'details', 'detail', 'info', 'information', 'note', 'notes',
    'short_description', 'long_description', 'full_description', 'product_description',
    'description_ar', 'description_en', 'about', 'summary', 'content', 'text', 'body',
    'وصف', 'الوصف', 'تفاصيل', 'التفاصيل', 'ملاحظات',
)
DESC_LANG_KEYS = ('ar', 'ar_SA', 'ar-SA', 'en', 'en_US', 'default')


def _desc_to_text(v):
    """يحوّل أي شكل للوصف (نص / HTML / قائمة نصوص / ترجمات) إلى نص عادي."""
    if isinstance(v, str):
        return _strip_html(v)
    if isinstance(v, list):
        parts = [_strip_html(x) for x in v if isinstance(x, str) and x.strip()]
        return '\n'.join(p for p in parts if p)
    if isinstance(v, dict):
        for lk in DESC_LANG_KEYS:
            if isinstance(v.get(lk), str) and v[lk].strip():
                return _strip_html(v[lk])
        parts = [_strip_html(x) for x in v.values() if isinstance(x, str) and x.strip()]
        return '\n'.join(p for p in parts if p)
    return ''


_DESC_SKIP_KEYS = ('params', 'qty_values', 'price', 'base_price', 'name', 'title', 'category_name',
                   'image', 'img', 'category_img', 'id', 'parent_id', 'available', 'product_type')


def _node_desc(d, _depth=0):
    """وصف حقيقي من الـ API فقط: الأسماء المعروفة أولاً، ثم أي حقل اسمه فيه desc/وصف/detail/تفاصيل،
    ثم الحقول المتداخلة (data / attributes / meta ...)."""
    if not isinstance(d, dict):
        return ''
    lowered = {str(k).strip().lower(): v for k, v in d.items()}
    for k in DESC_KEYS:
        v = d.get(k)
        if v in (None, '', [], {}):
            v = lowered.get(k.lower())
        text = _desc_to_text(v)
        if text:
            return text
    for kl, v in lowered.items():
        if kl in _DESC_SKIP_KEYS:
            continue
        if any(w in kl for w in ('desc', 'وصف', 'detail', 'تفاصيل')):
            text = _desc_to_text(v)
            if text:
                return text
    if _depth < 2:
        for k in ('data', 'attributes', 'attribute', 'meta', 'product', 'category', 'extra', 'extras', 'info'):
            sub = lowered.get(k)
            if isinstance(sub, dict):
                t = _node_desc(sub, _depth + 1)
                if t:
                    return t
    return ''


def _node_desc_fallback(d):
    """لو المزود ما عنده وصف: نبني وصفاً من معلومات الـ API نفسها (المطلوب + الكمية)."""
    if not isinstance(d, dict):
        return ''
    lines = []
    params = d.get('params')
    if isinstance(params, list):
        labels = [str(p).strip() for p in params if str(p).strip()]
        if labels:
            lines.append('المطلوب: ' + ' - '.join(labels))
    qty = d.get('qty_values')
    if isinstance(qty, dict) and (qty.get('min') not in (None, '') or qty.get('max') not in (None, '')):
        lines.append(f"الكمية: من {qty.get('min', 1)} إلى {qty.get('max', '∞')}")
    elif isinstance(qty, list) and qty:
        lines.append('الكميات المتاحة: ' + ' ، '.join(str(q) for q in qty))
    return '\n'.join(lines)


def api_description(*nodes):
    """وصف الفئة الحقيقي من الـ API فقط (العقدة نفسها ثم قائمة المنتجات).
    ما عاد نبني وصفاً من متطلبات الشراء (المطلوب/الكمية) لأن هذي بتظهر كمستطيلات إدخال بنافذة الشراء."""
    for n in nodes:
        t = _node_desc(n)
        if t:
            return t, True
    return '', False


def _api_param_labels(*nodes):
    """أسماء متطلبات الشراء من الـ API (params) بنفس الترتيب. مثال: ["ادخل الايدي", "السيرفر"]."""
    for n in nodes:
        if not isinstance(n, dict):
            continue
        ps = n.get('params')
        if not isinstance(ps, list):
            continue
        labels = []
        for it in ps:
            if isinstance(it, dict):
                it = _first_value(it, ('label', 'name', 'title', 'key'))
            it = str(it or '').strip()
            if it and it not in labels:
                labels.append(it)
        if labels:
            return labels
    return []


def _is_auto_desc(text, node):
    """هل هذا الوصف هو النص القديم المبني تلقائياً من المتطلبات؟ (لتنظيفه من الفئات المسحوبة سابقاً)"""
    text = (text or '').strip()
    if not text:
        return False
    return text == _node_desc_fallback(node).strip() or text.startswith('المطلوب:') or text.startswith('الكميات المتاحة:')


def _abs_img(base_url, img):
    if not img or not isinstance(img, str):
        return ''
    if img.startswith('http') or img.startswith('data:'):
        return img
    return base_url.rstrip('/') + '/' + img.lstrip('/')


def _node_image(base_url, d):
    return _abs_img(base_url, _first_value(d, ('image', 'img', 'category_img', 'icon', 'logo', 'photo')))


def _to_float(v, default=0.0):
    try:
        return float(v)
    except Exception:
        return default


def _split_lists(section):
    """يفصل أي رد من الـ API إلى (أقسام فرعية، منتجات قابلة للشراء) بنفس ترتيب الـ API."""
    cats, prods = [], []
    if isinstance(section, dict):
        for k in ('categories', 'subcategories', 'sub_categories', 'children', 'sections'):
            if isinstance(section.get(k), list):
                cats = section[k]
                break
        for k in ('products', 'items', 'packages'):
            if isinstance(section.get(k), list):
                prods = section[k]
                break
    elif isinstance(section, list):
        for it in section:
            if not isinstance(it, dict):
                continue
            if 'price' in it or 'product_type' in it or 'qty_values' in it:
                prods.append(it)
            else:
                cats.append(it)
    return [c for c in cats if isinstance(c, dict)], [p for p in prods if isinstance(p, dict)]


def _extract_content_lists(content):
    section = content
    if isinstance(content, dict):
        if isinstance(content.get('data'), (dict, list)):
            section = content['data']
    return _split_lists(section)


def get_import_state(provider_name, original_name):
    """حالة قسم مستورد سابقاً: مستورد؟ نسخة قديمة؟ وبياناته."""
    info = API_IMPORTS_DATA.get(f"{provider_name}_{original_name}")
    if info is None:
        for v in API_IMPORTS_DATA.values():
            if v.get('original_category_name') == original_name and (not provider_name or v.get('provider_name') == provider_name):
                info = v
                break
    if not info:
        return {"already_imported": False, "legacy": False, "import_info": None}
    legacy = int(info.get('schema_version', 1)) < API_IMPORT_SCHEMA
    return {
        "already_imported": True,
        "legacy": legacy,
        "import_info": {
            "category_name": info.get('category_name', ''),
            "profit_margin": info.get('profit_margin', 0),
            "imported_at": info.get('imported_at', ''),
            "status": info.get('status', 'done')
        }
    }


def _job_snapshot(job):
    with IMPORT_JOBS_LOCK:
        return {
            "job_id": job['id'],
            "status": job['status'],
            "phase": job['phase'],
            "current": job['current'],
            "percent": job['percent'],
            "counts": dict(job['counts']),
            "stats": dict(job['stats']),
            "message": job.get('message', ''),
            "log": list(job['log'][-12:])
        }


def _job_set(job, **kw):
    with IMPORT_JOBS_LOCK:
        job.update(kw)


def _job_inc(job, key, n=1):
    with IMPORT_JOBS_LOCK:
        job['counts'][key] = job['counts'].get(key, 0) + n


def _job_stat(job, key, n=1):
    with IMPORT_JOBS_LOCK:
        job['stats'][key] = job['stats'].get(key, 0) + n


def _job_log(job, msg):
    with IMPORT_JOBS_LOCK:
        job['log'].append(f"{datetime.now().strftime('%H:%M:%S')}  {msg}")
        del job['log'][:-60]


class ApiTreeImport:
    def __init__(self, job, provider_name, token, base_url, root_id, site_category,
                 original_name, margin, image, api_image, replace_legacy):
        self.job = job
        self.provider_name = provider_name
        self.token = token
        self.base_url = base_url if base_url.endswith('/') else base_url + '/'
        self.root_id = root_id
        self.site_category = site_category
        self.original_name = original_name
        self.margin = margin
        self.image = image
        self.api_image = api_image
        self.replace_legacy = replace_legacy
        self.import_key = f"{provider_name}_{original_name}"
        self.visited = set()
        self.products_map = {}
        self.discovered = 1
        self.processed = 0

    # ---------- أدوات ----------
    def check_cancel(self):
        if self.job.get('cancel'):
            raise ImportCancelled()

    def log(self, msg):
        _job_log(self.job, msg)
        logging.info(f"[استيراد {self.import_key}] {msg}")

    def pause(self, seconds):
        # انتظار على دفعات صغيرة حتى يستجيب زر الإلغاء بسرعة
        end = time.time() + seconds
        while time.time() < end:
            self.check_cancel()
            time.sleep(min(0.1, max(0.0, end - time.time())))

    def update_percent(self):
        pct = int(100 * self.processed / max(self.discovered, 1))
        _job_set(self.job, percent=min(pct, 99))

    def save_all(self):
        with DATA_LOCK:
            save_json_file(PRODUCTS_FILE, PRODUCTS_DATA)
            save_json_file(SUBCATEGORIES_FILE, SUBCATEGORIES_DATA)
            save_json_file(SUBCATEGORY_GROUPS_FILE, SUBCATEGORY_GROUPS_DATA)

    # ---------- جلب ----------
    def fetch_content(self, node_id):
        url = f"{self.base_url}client/api/content/{urllib.parse.quote(str(node_id), safe='')}"
        last = None
        for attempt in range(3):
            self.check_cancel()
            try:
                res = make_api_request(url, self.token, timeout=25)
                if isinstance(res, dict) and res.get('error') and not res.get('data'):
                    raise Exception(f"خطأ من المزود ({res.get('error')}): {res.get('message', '')}")
                return res
            except ImportCancelled:
                raise
            except Exception as e:
                last = e
                self.pause(1.5 * (attempt + 1))
        raise last

    def load_products_map(self):
        try:
            lst = make_api_request(f"{self.base_url}client/api/products", self.token, timeout=40)
            if isinstance(lst, list):
                for ap in lst:
                    if isinstance(ap, dict) and ap.get('id') is not None:
                        self.products_map[str(ap['id'])] = ap
            self.log(f"تم تحميل قائمة الأسعار ({len(self.products_map)} منتج)")
        except Exception as e:
            self.log(f"تحذير: تعذر تحميل قائمة الأسعار: {e}")

    def get_children(self, node_id, node=None):
        cats, prods, ok = [], [], False
        try:
            cats, prods = _extract_content_lists(self.fetch_content(node_id))
            ok = True
        except ImportCancelled:
            raise
        except Exception as e:
            self.log(f"تعذر قراءة محتوى {node_id}: {e}")
            _job_stat(self.job, 'errors')
        if not cats and not prods and isinstance(node, dict):
            # بعض الردود تحمل الأبناء داخل القسم نفسه
            cats, prods = _split_lists(node)
        if not prods and str(node_id) not in ('0', ''):
            flat = [ap for ap in self.products_map.values()
                    if str(ap.get('parent_id')) == str(node_id) and ap.get('id') is not None]
            if flat:
                prods = flat
        self.pause(IMPORT_STEP_DELAY)
        return cats, prods

    # ---------- تنظيف النسخة القديمة ----------
    def cleanup_legacy(self):
        with DATA_LOCK:
            old_subs = [s for s in SUBCATEGORIES_DATA
                        if s.get('imported_from_api') and not s.get('api_v2') and s.get('api_import_key') == self.import_key]
            for s in old_subs:
                SUBCATEGORIES_DATA.remove(s)
            used = {s.get('product') for s in SUBCATEGORIES_DATA}
            old_prods = [p for p in PRODUCTS_DATA
                         if p.get('category') == self.site_category and not p.get('api_v2')
                         and p.get('name') not in used]
            for p in old_prods:
                PRODUCTS_DATA.remove(p)
            self.log(f"تم حذف النسخة القديمة: {len(old_subs)} فئة و {len(old_prods)} منتج")
            self.save_all()

    # ---------- إنشاء عناصر المتجر ----------
    def _unique_product_name(self, base, api_id):
        names = {p.get('name') for p in PRODUCTS_DATA}
        if base not in names:
            return base
        cand = f"{base} ({self.site_category})"
        if cand not in names:
            return cand
        i = 2
        cand = f"{base} ({api_id})"
        while cand in names:
            cand = f"{base} ({api_id}-{i})"
            i += 1
        return cand

    def ensure_site_product(self, api_id, name, image):
        with DATA_LOCK:
            ex = next((p for p in PRODUCTS_DATA
                       if p.get('api_import_key') == self.import_key
                       and str(p.get('api_node_id')) == str(api_id)
                       and p.get('category') == self.site_category), None)
            if ex is None:
                ex = next((p for p in PRODUCTS_DATA
                           if p.get('name') == name and p.get('category') == self.site_category
                           and not p.get('api_node_id')), None)
                if ex is not None:
                    ex['api_import_key'] = self.import_key
                    ex['api_node_id'] = str(api_id)
                    ex['api_v2'] = True
            if ex is not None:
                if image and not ex.get('image'):
                    ex['image'] = image
                return ex['name']
            unique = self._unique_product_name(name, api_id)
            PRODUCTS_DATA.append({
                "name": unique,
                "category": self.site_category,
                "image": image or '',
                "api_import_key": self.import_key,
                "api_node_id": str(api_id),
                "api_v2": True
            })
            return unique

    def ensure_group(self, site_product, api_id, name, image):
        with DATA_LOCK:
            groups = SUBCATEGORY_GROUPS_DATA.setdefault(site_product, [])
            ex = next((g for g in groups
                       if g.get('api_import_key') == self.import_key and str(g.get('api_node_id')) == str(api_id)), None)
            if ex is None:
                ex = next((g for g in groups if g.get('name') == name and not g.get('api_node_id')), None)
                if ex is not None:
                    ex['api_import_key'] = self.import_key
                    ex['api_node_id'] = str(api_id)
                    ex['api_v2'] = True
            if ex is not None:
                if image and not ex.get('image'):
                    ex['image'] = image
                return ex['id']
            gid = str(uuid.uuid4())
            groups.append({
                "id": gid,
                "name": name,
                "image": image or '',
                "created_at": datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
                "api_import_key": self.import_key,
                "api_node_id": str(api_id),
                "api_v2": True
            })
            return gid

    def add_leaf(self, p, site_product, group_id, prefix):
        pid = p.get('id')
        if pid is None:
            return
        pid_s = str(pid)
        extra = self.products_map.get(pid_s, {})
        src = dict(p)
        for k, v in extra.items():
            if k != 'name' and (k not in src or src.get(k) in (None, '', [], {})):
                src[k] = v
        for k in ('base_price', 'price', 'qty_values', 'product_type'):
            if k in extra:
                src[k] = extra[k]

        name = _node_name(p) or _node_name(extra) or f"فئة {pid_s}"
        if prefix:
            name = f"{prefix} - {name}"

        base_raw = src.get('base_price')
        base_price = _to_float(base_raw if base_raw not in (None, '') else src.get('price'))
        price = round(base_price * (1 + self.margin / 100.0), 10)
        desc, desc_is_real = api_description(p, extra)
        if not desc and getattr(self, '_desc_miss_logged', 0) < 3:
            self._desc_miss_logged = getattr(self, '_desc_miss_logged', 0) + 1
            logging.info(f"[وصف] المزود ما رجّع وصف للفئة {pid_s}. الحقول المتاحة: {sorted(str(k) for k in src.keys())}")
        param_labels = _api_param_labels(src, p, extra)
        image = _node_image(self.base_url, p) or _node_image(self.base_url, extra)

        is_counter, cmin, cmax = False, 1, None
        qty = src.get('qty_values')
        if isinstance(qty, dict):
            is_counter = True
            cmin = max(1, int(_to_float(qty.get('min'), 1)))
            cmax = int(_to_float(qty.get('max'))) if qty.get('max') not in (None, '') else None
        elif isinstance(qty, list) and qty:
            nums = [int(_to_float(q)) for q in qty if _to_float(q) > 0]
            if nums:
                is_counter, cmin, cmax = True, min(nums), max(nums)

        with DATA_LOCK:
            ex = next((s for s in SUBCATEGORIES_DATA
                       if s.get('provider_name') == self.provider_name
                       and str(s.get('api_product_id')) == pid_s
                       and s.get('product') == site_product
                       and (s.get('group_id') or None) == (group_id or None)), None)
            if ex is not None:
                ex['base_price'] = base_price
                ex['price'] = price
                ex['profit_margin'] = self.margin
                ex['api_import_key'] = self.import_key
                ex['imported_from_api'] = True
                ex['api_v2'] = True
                if desc:
                    ex['description'] = desc
                    ex['desc_api'] = True
                elif ex.get('desc_api') and _is_auto_desc(ex.get('description'), src):
                    # وصف قديم مبني من المتطلبات → نشيله (المتطلبات صارت مستطيلات بنافذة الشراء)
                    ex['description'] = ''
                    ex['desc_api'] = False
                if param_labels:
                    ex['api_params'] = param_labels
                else:
                    ex.pop('api_params', None)
                if image and not ex.get('image'):
                    ex['image'] = image
                if is_counter:
                    ex['is_counter'] = True
                    ex['counter_min_qty'] = cmin
                    ex['counter_max_qty'] = cmax
                    ex['api_unit_price'] = True
                    set_counter_unit_price(ex, price)
                _job_stat(self.job, 'updated')
            else:
                new_sub = {
                    "name": name,
                    "price": price,
                    "base_price": base_price,
                    "product": site_product,
                    "provider_name": self.provider_name,
                    "api_product_id": pid_s,
                    "description": desc,
                    "image": image,
                    "is_counter": is_counter,
                    "imported_from_api": True,
                    "api_import_key": self.import_key,
                    "api_v2": True,
                    "desc_api": bool(desc),
                    "profit_margin": self.margin
                }
                if param_labels:
                    new_sub['api_params'] = param_labels
                if group_id:
                    new_sub['group_id'] = group_id
                if is_counter:
                    new_sub['counter_min_qty'] = cmin
                    new_sub['counter_max_qty'] = cmax
                    new_sub['api_unit_price'] = True
                    set_counter_unit_price(new_sub, price)
                SUBCATEGORIES_DATA.append(new_sub)
                _job_stat(self.job, 'added')
        _job_inc(self.job, 'categories')
        time.sleep(IMPORT_ITEM_DELAY)

    # ---------- المشي على الشجرة ----------
    def process_node(self, node_id, node, level, site_product=None, group_id=None, prefix=''):
        self.check_cancel()
        key = str(node_id)
        if key in self.visited or level > IMPORT_MAX_DEPTH:
            self.processed += 1
            return
        self.visited.add(key)

        name = _node_name(node) if node else self.original_name
        labels = {0: 'القسم', 1: 'القسم الفرعي', 2: 'المنتج'}
        _job_set(self.job, current=name, phase=f"جاري سحب {labels.get(level, 'المحتوى')}: {name}")

        cats, prods = self.get_children(node_id, node)
        self.discovered += len(cats)

        def do_children():
            for c in cats:
                self.check_cancel()
                cid = c.get('id')
                cname = _node_name(c)
                if cid is None or not cname:
                    self.processed += 1
                    continue
                cimg = _node_image(self.base_url, c)
                if level == 0:
                    sp = self.ensure_site_product(cid, cname, cimg)
                    _job_inc(self.job, 'subsections')
                    self.process_node(cid, c, 1, site_product=sp)
                elif level == 1:
                    gid = self.ensure_group(site_product, cid, cname, cimg)
                    _job_inc(self.job, 'products')
                    self.process_node(cid, c, 2, site_product=site_product, group_id=gid)
                else:
                    new_prefix = f"{prefix} - {cname}" if prefix else cname
                    self.process_node(cid, c, level + 1, site_product=site_product, group_id=group_id, prefix=new_prefix)

        def do_leaves():
            if not prods:
                return
            target_product, target_group = site_product, group_id
            if level == 0:
                # فئات مباشرة تحت القسم الرئيسي: نضعها بمنتج يحمل اسم القسم
                target_product = self.ensure_site_product(f"root-{node_id}", self.original_name, '')
                target_group = None
                _job_inc(self.job, 'subsections')
            for p in prods:
                self.check_cancel()
                self.add_leaf(p, target_product, target_group, prefix if level >= 3 else '')

        if level >= 2:
            # داخل المنتج: فئاته أولاً ثم ما تفرّع منه (مسطّحاً)
            do_leaves()
            do_children()
        else:
            do_children()
            do_leaves()

        self.processed += 1
        self.update_percent()
        if level <= 1:
            self.save_all()

    # ---------- التشغيل ----------
    def run(self):
        job = self.job
        try:
            _job_set(job, status='running', phase='تجهيز الاستيراد...')
            with DATA_LOCK:
                if self.replace_legacy:
                    self.cleanup_legacy()
                if self.image:
                    CATEGORIES_DATA[self.site_category] = self.image
                elif not CATEGORIES_DATA.get(self.site_category):
                    CATEGORIES_DATA[self.site_category] = self.api_image or ''
                save_json_file(CATEGORIES_FILE, CATEGORIES_DATA)
                API_IMPORTS_DATA[self.import_key] = {
                    "provider_name": self.provider_name,
                    "original_category_name": self.original_name,
                    "category_name": self.site_category,
                    "category_id": self.root_id,
                    "profit_margin": self.margin,
                    "imported_at": datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
                    "last_price_check": datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
                    "schema_version": API_IMPORT_SCHEMA,
                    "status": "importing"
                }
                save_json_file(API_IMPORTS_FILE, API_IMPORTS_DATA)

            _job_set(job, phase='جاري تحميل قائمة الأسعار...')
            self.load_products_map()
            self.pause(IMPORT_STEP_DELAY)

            root_node = {"id": self.root_id, "name": self.original_name}
            self.process_node(self.root_id, root_node, 0)
            self.save_all()

            counts = dict(job['counts'])
            with DATA_LOCK:
                info = API_IMPORTS_DATA.get(self.import_key, {})
                info.update({
                    "last_price_check": datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
                    "schema_version": API_IMPORT_SCHEMA,
                    "status": "done",
                    "subsections_count": counts.get('subsections', 0),
                    "products_count": counts.get('products', 0),
                    "categories_count": counts.get('categories', 0),
                    "subcategories_count": counts.get('categories', 0)
                })
                API_IMPORTS_DATA[self.import_key] = info
                save_json_file(API_IMPORTS_FILE, API_IMPORTS_DATA)

            if counts.get('categories', 0) == 0:
                _job_set(job, status='done', percent=100, phase='انتهى السحب', current='',
                         message='ما وصلت أي فئة من المزود. تحقق من التوكن والرابط ومن أن القسم فيه محتوى.')
            else:
                _job_set(job, status='done', percent=100, phase='اكتمل الاستيراد', current='',
                         message='تم سحب الشجرة كاملة بنجاح')
            self.log("اكتمل الاستيراد")
        except ImportCancelled:
            self.save_all()
            with DATA_LOCK:
                if self.import_key in API_IMPORTS_DATA:
                    API_IMPORTS_DATA[self.import_key]['status'] = 'cancelled'
                    save_json_file(API_IMPORTS_FILE, API_IMPORTS_DATA)
            _job_set(job, status='cancelled', phase='تم إيقاف الاستيراد', current='',
                     message='تم إيقاف الاستيراد. ما انسحب حتى الآن محفوظ، وتقدر تعيد السحب لتكملة الباقي.')
            self.log("تم إلغاء الاستيراد من الأدمن")
        except Exception as e:
            logging.error(f"خطأ في استيراد {self.import_key}: {e}")
            try:
                self.save_all()
            except Exception:
                pass
            _job_set(job, status='error', phase='فشل الاستيراد', current='', message=str(e))


def start_api_tree_import(provider_name, token, base_url, root_id, site_category,
                          original_name, margin, image, api_image, replace_legacy):
    import_key = f"{provider_name}_{original_name}"
    with IMPORT_JOBS_LOCK:
        for j in IMPORT_JOBS.values():
            if j['import_key'] == import_key and j['status'] in ('queued', 'running'):
                return j, True
        job = {
            "id": uuid.uuid4().hex[:12],
            "import_key": import_key,
            "status": "queued",
            "phase": "في الانتظار...",
            "current": "",
            "percent": 0,
            "counts": {"subsections": 0, "products": 0, "categories": 0},
            "stats": {"added": 0, "updated": 0, "errors": 0},
            "message": "",
            "log": [],
            "cancel": False,
            "created": time.time()
        }
        IMPORT_JOBS[job['id']] = job
        finished = sorted([j for j in IMPORT_JOBS.values() if j['status'] not in ('queued', 'running')],
                          key=lambda x: x['created'])
        for old in finished[:-15]:
            IMPORT_JOBS.pop(old['id'], None)
    importer = ApiTreeImport(job, provider_name, token, base_url, root_id, site_category,
                             original_name, margin, image, api_image, replace_legacy)
    threading.Thread(target=importer.run, daemon=True).start()
    return job, False


# تنبيه عند الإقلاع: أقسام مستوردة بالصيغة القديمة تحتاج إعادة سحب
_legacy_imports = [k for k, v in API_IMPORTS_DATA.items() if int(v.get('schema_version', 1)) < API_IMPORT_SCHEMA]
if _legacy_imports:
    logging.warning(f"يوجد {len(_legacy_imports)} قسم مستورد بالنسخة القديمة؛ استخدم زر (إعادة السحب) من لوحة الأدمن لتحديثها.")



