            APPEARANCE_DATA['dark_text_color'] = data.get('dark_text_color', '#ffffff')
            APPEARANCE_DATA['dark_subtext_color'] = data.get('dark_subtext_color', '#a1a1aa')
            APPEARANCE_DATA['dark_sidebar_bg'] = data.get('dark_sidebar_bg', '#09090f')
